const axios = require('axios');
const readlineSync = require('readline-sync');

async function 3bic(capcutUrl) {
    const endpoint = 'https://3bic.com/api/download';

    const headers = {
        'Content-Type': 'application/json',
        'Origin': 'https://3bic.com',
        'Referer': 'https://3bic.com/',
        'User-Agent': 'Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/139.0.0.0 Mobile Safari/537.36',
        'Sec-Fetch-Dest': 'empty',
        'Sec-Fetch-Mode': 'cors',
        'Sec-Fetch-Site': 'same-origin'
    };

    const payload = {
        url: capcutUrl
    };

    try {
        const response = await axios.post(endpoint, payload, { headers, timeout: 10000 });
        const resData = response.data;

        if (resData && resData.code === 200) {
            let downloadUrl = resData.originalVideoUrl || '';
            if (downloadUrl.startsWith('/')) {
                downloadUrl = `https://3bic.com${downloadUrl}`;
            }

            const output = {
                status: true,
                message: 'Berhasil mengambil data video CapCut',
                data: {
                    title: resData.title || '',
                    author: resData.authorName || '',
                    cover_url: resData.coverUrl || '',
                    download_url: downloadUrl,
                    raw_response: resData
                }
            };

            process.stdout.write(JSON.stringify(output, null, 2) + '\n');
        } else {
            throw new Error(resData.message || 'Gagal memproses URL CapCut.');
        }

    } catch (err) {
        const errorOutput = {
            status: false,
            message: 'Gagal melakukan scraping',
            error: err.response?.data || err.message
        };
        process.stdout.write(JSON.stringify(errorOutput, null, 2) + '\n');
        process.exit(1);
    }
}

(async () => {
    let inputUrl = process.argv[2];

    if (!inputUrl) {
        inputUrl = readlineSync.question('Masukkan Link CapCut: ');
    }

    if (!inputUrl || !inputUrl.includes('capcut.com')) {
        const errorOutput = {
            status: false,
            message: 'URL CapCut tidak valid.'
        };
        process.stdout.write(JSON.stringify(errorOutput, null, 2) + '\n');
        process.exit(1);
    }

    await 3bic(inputUrl.trim());
})();

const axios = require('axios');
