async function sendMagicLink(email) {
    console.log(`[1/3] Mengirim Magic Link ke: ${email}...`);

    const res = await axios.post(`${BASE_URL}/api/satriam/send-link`, 
        { email }, 
        { headers: HEADERS, timeout: 15000 }
    );

    if (!res.data?.success) {
        throw new Error(`Gagal kirim link: ${JSON.stringify(res.data)}`);
    }

    console.log(`   [+] Status: ${res.data.message}`);
    return true;
}

async function verifyMagicLink(email, magicLink) {
    console.log(`\n[2/3] Memverifikasi Magic Link...`);

    const payload = {
        email: email,
        magicLink: magicLink
    };

    const res = await axios.post(`${BASE_URL}/api/satriam/verify-link`, 
        payload, 
        { headers: HEADERS, timeout: 15000 }
    );

    if (!res.data?.success) {
        throw new Error(`Verifikasi gagal: ${JSON.stringify(res.data)}`);
    }

    console.log(`   [+] Verifikasi Berhasil!`);
    console.log(`   [+] UID: ${res.data.uid}`);
    console.log(`   [+] Plan: ${res.data.planName}`);
    console.log(`   [+] Valid Until: ${res.data.validUntil}`);

    return res.data;
}

async function autoLogin(email) {
    await sendMagicLink(email);    
    console.log(`\n[WAITING] Silakan cek inbox email ${email} dan copy URL Magic Link-nya.`);
    console.log(`[INPUT] Paste Magic Link di sini lalu tekan Enter:`);

    const magicLink = await new Promise((resolve) => {
        process.stdin.resume();
        process.stdin.setEncoding('utf8');
        process.stdin.once('data', (data) => {
            process.stdin.pause();
            resolve(data.trim());
        });
    });

    if (!magicLink.startsWith('http')) {
        throw new Error('Input bukan URL Magic Link yang valid.');
    }

    const result = await verifyMagicLink(email, magicLink);

    const outFile = `satriam_${email.replace(/[@.]/g, '_')}.json`;
    fs.writeFileSync(outFile, JSON.stringify(result, null, 2));
    return result;
}

